  CREATE PROCEDURE [bud].[jsCompareDocEntryWithDraftApproval]  AS  BEGIN      SET NOCOUNT ON;        -- Step 1: Temp table for HANA proc result      IF OBJECT_ID('tempdb..#DraftApproval') IS NOT NULL          DROP TABLE #DraftApproval;        CREATE TABLE #DraftApproval (          Branch NVARCHAR(50),          DocEntry INT,          ObjectName NVARCHAR(100),          ObjType NVARCHAR(20),          LineNum INT,          VisOrder INT,          AcctCode NVARCHAR(50),          AcctName NVARCHAR(200),          CardCode NVARCHAR(50),          CardName NVARCHAR(200),          EFFECTMONTH NVARCHAR(20),          BUDGET NVARCHAR(50),          SUB_BUDGET NVARCHAR(50),          STATE NVARCHAR(20),          DocDate DATETIME,          CreateDate DATETIME,          AMOUNT DECIMAL(18,4),          CURRENTMONTH NVARCHAR(20),          Current_month_Posted_Amount DECIMAL(18,4),          Budget_Owner NVARCHAR(100),          OwnerCode NVARCHAR(50),          [Approver Name] NVARCHAR(100),          ApprovalCode NVARCHAR(50),          Current_month_Budget DECIMAL(18,4),          Status NVARCHAR(10),          U_NAME NVARCHAR(100),          CreatedDate DATETIME,          CreateTime NVARCHAR(50),          LineRemarks NVARCHAR(MAX),          Comments NVARCHAR(MAX),          ProcesStat NVARCHAR(10),          UpdateDate DATETIME,          OcrCode NVARCHAR(50),          ACOMMENT NVARCHAR(MAX),          VCOMMENT NVARCHAR(MAX),          VerifiedStatus NVARCHAR(10),          ApprovedStatus NVARCHAR(10)      );        -- Step 2: Insert HANA proc result      INSERT INTO #DraftApproval      EXEC ('CALL "JIVO_OIL_HANADB"."DRAFT_APPROVAL"') AT HANA112;        -- Step 3: Compare with jsDocEntry + join jsBudgetTable      SELECT           -- jsDocEntry          A.id,          A.docEntry,          A.status,          A.currentStageId,          A.templateId,          A.totalStage,          A.currentSatge,          A.date,          A.updatedOn,          A.createdOn,            -- jsBudgetTable          B.Branch,          B.ObjectName,          B.ObjType,          B.LineNum,          B.VisOrder,          B.AcctCode,          B.AcctName,          B.CardCode,          B.CardName,          B.EFFECTMONTH,          B.BUDGET,          B.SUB_BUDGET,          B.STATE,          B.DocDate,          B.CreateDate,          B.AMOUNT,          B.CURRENTMONTH,          B.Current_month_Posted_Amount,          B.Budget_Owner,          B.OwnerCode,          B.[Approver Name],          B.ApprovalCode,          B.Current_month_Budget,          B.Status AS BudgetStatus,          B.U_NAME,          B.CreatedDate,          B.CreateTime,          B.LineRemarks,          B.Comments,          B.ProcesStat,          B.UpdateDate,          B.OcrCode,          B.ACOMMENT,          B.VCOMMENT,          B.VerifiedStatus,          B.ApprovedStatus,          B.flag,          B.budgetDate        FROM bud.jsDocEntry A      LEFT JOIN #DraftApproval H          ON A.docEntry = H.DocEntry      INNER JOIN bud.jsBudgetTable B          ON A.docEntry = B.DocEntry      WHERE A.status = 'A'        AND H.DocEntry IS NULL;  -- means missing in HANA proc  END;
